package clinical

import (
	"sort"
)

// RecordHistory 是内部使用者看到的一条记录的完整视图：
// 草稿（若有）与全部历史版本（旧到新，含更正原因）。
type RecordHistory struct {
	Record         Record
	DraftContent   string
	HasDraft       bool
	CurrentVersion *Version
	Versions       []Version // 旧到新
}

// PatientChart 是内部使用者按患者看到的完整档案。
type PatientChart struct {
	Patient     Patient
	Encounters  []Encounter
	Records     []RecordHistory
	AuditEvents []AuditEvent
}

// Chart 返回患者的完整档案，包含所有草稿、全部版本（含旧内容、版本关系
// 与更正原因）以及审计事件。仅供内部使用者；患者停用后仍可查看。
func (s *Store) Chart(actor Actor, patientID ID) (PatientChart, error) {
	if !actor.valid() || !actor.IsInternal() {
		return PatientChart{}, ErrAccessDenied
	}
	var chart PatientChart
	err := s.view(func(snap *snapshot) error {
		p, err := requirePatient(snap, patientID)
		if err != nil {
			return err
		}
		chart.Patient = *p

		for _, e := range snap.Encounters {
			if e.PatientID == patientID {
				chart.Encounters = append(chart.Encounters, *e)
			}
		}
		sortEncounters(chart.Encounters)

		var recs []*Record
		for _, r := range snap.Records {
			if r.PatientID == patientID {
				recs = append(recs, r)
			}
		}
		sort.Slice(recs, func(i, j int) bool { return recs[i].ID < recs[j].ID })

		for _, r := range recs {
			chart.Records = append(chart.Records, buildHistory(snap, r))
		}

		for _, ev := range snap.AuditEvents {
			if ev.PatientID == patientID {
				// 审计事件按追加顺序保存，即真实发生顺序；
				// 时间戳相同（如注入时钟）时也不能打乱。
				chart.AuditEvents = append(chart.AuditEvents, *ev)
			}
		}
		return nil
	})
	return chart, err
}

// AuditEvents 仅供内部使用者按患者查看审计事件，按发生时间旧到新。
func (s *Store) AuditEvents(actor Actor, patientID ID) ([]AuditEvent, error) {
	chart, err := s.Chart(actor, patientID)
	if err != nil {
		return nil, err
	}
	return chart.AuditEvents, nil
}

// EncounterRecords 仅供内部使用者查看某次就诊下的记录及完整历史。
func (s *Store) EncounterRecords(actor Actor, patientID, encounterID ID) ([]RecordHistory, error) {
	if !actor.valid() || !actor.IsInternal() {
		return nil, ErrAccessDenied
	}
	var out []RecordHistory
	err := s.view(func(snap *snapshot) error {
		if _, err := requirePatient(snap, patientID); err != nil {
			return err
		}
		if _, err := requireEncounter(snap, patientID, encounterID); err != nil {
			return err
		}
		var recs []*Record
		for _, r := range snap.Records {
			if r.EncounterID == encounterID {
				recs = append(recs, r)
			}
		}
		sort.Slice(recs, func(i, j int) bool { return recs[i].ID < recs[j].ID })
		for _, r := range recs {
			out = append(out, buildHistory(snap, r))
		}
		return nil
	})
	return out, err
}

func buildHistory(snap *snapshot, r *Record) RecordHistory {
	// 返回的记录必须是独立副本：Versions 切片与存储中的记录共享底层数组时，
	// 调用方改动查询结果会写回正式历史。这里深拷贝，保证修改手中的结果
	// 只影响该结果本身。
	rec := *r
	rec.Versions = append([]ID(nil), r.Versions...)
	rh := RecordHistory{
		Record:       rec,
		DraftContent: r.DraftContent,
		HasDraft:     r.HasDraft,
	}
	for _, vid := range r.Versions {
		if v := snap.Versions[vid]; v != nil {
			rh.Versions = append(rh.Versions, *v)
		}
	}
	sort.Slice(rh.Versions, func(i, j int) bool { return rh.Versions[i].Number < rh.Versions[j].Number })
	if r.CurrentVersionID != "" {
		if v := snap.Versions[r.CurrentVersionID]; v != nil {
			cv := *v
			rh.CurrentVersion = &cv
		}
	}
	return rh
}

// currentEffective 取出记录当前生效版本的对外内容；无生效版本时第二返回值为 false。
func currentEffective(snap *snapshot, r *Record) (EffectiveRecord, bool) {
	if r.CurrentVersionID == "" {
		return EffectiveRecord{}, false
	}
	v := snap.Versions[r.CurrentVersionID]
	if v == nil {
		return EffectiveRecord{}, false
	}
	return EffectiveRecord{
		RecordID:    r.ID,
		VersionID:   v.ID,
		Version:     v.Number,
		Content:     v.Content,
		EffectiveAt: v.CreatedAt,
	}, true
}

func sortEncounters(es []Encounter) {
	sort.Slice(es, func(i, j int) bool {
		if !es[i].OccurredAt.Equal(es[j].OccurredAt) {
			return es[i].OccurredAt.Before(es[j].OccurredAt)
		}
		return es[i].ID < es[j].ID
	})
}

// Package clinical 提供在本机运行的临床档案与授权查阅能力，只处理合成患者资料。
//
// 基本用法是先用 [Open] 在调用方指定的数据目录打开一个 [Store]：
//
//	s, err := clinical.Open("/path/to/data")
//
// 所有写操作都由内部使用者（[InternalActor]）执行：登记患者（Store.RegisterPatient）、
// 登记就诊（Store.AddEncounter）、在就诊下录入诊断或医嘱草稿
// （Store.CreateDraft / Store.UpdateDraft / Store.DeleteDraft），草稿确认后
// 用 Store.ActivateRecord 生效。生效记录不可覆盖或删除，只能用
// Store.CorrectRecord 更正：更正需提供非空原因并指明显式当前版本号，
// 成功后生成新版本，旧内容、版本关系（Version.PrevID）与原因全部保留；
// 指定版本已过期则返回 [ErrConflict] 且状态不变。
//
// 内部使用者用 Store.Chart 查看某患者的全部草稿与完整版本历史；
// 用 Store.Grant 为接收方（[ReceiverActor]）建立按“就诊+类别”限定、
// 带 [开始, 截止) 时间窗的整类授权，或用 Store.GrantSelective 在整类
// 范围之外再明确选出若干已生效记录（整类范围与选定记录范围可并存、
// 可跨多个就诊与类别），可用 Store.Revoke 提前撤回。
// 接收方用 Store.Read 按自己的身份读取：只返回所有当前有效授权允许记录
// 的当前生效版本合集，每条记录只出现一次；看不到草稿、旧版本或更正原因。
// 被选记录被更正后读到当前版本，但同类其他记录与后来新增生效的记录不会
// 自动进入限定范围；撤回整类授权后只剩其他有效授权明确允许的记录。
//
// 内部使用者可用 Store.CreateExchange 把一条当前有效授权覆盖的已生效记录
// 集合打包给指定接收方：所选每条记录都必须被绑定的那一条授权自身覆盖
// （整类或选定记录），不能借用同一接收方的其他授权补足；包只含患者与
// 接收方标识及各记录创建时的当前版本（就诊、类别、记录与版本标识、版本号、
// 生效时间与完整内容），并附稳定摘要，状态为待回执；包一旦创建即固定，
// 此后的更正或新增记录不会改写它。
// 请求号按内部使用者区分，相同请求号与相同参数重试返回原交换及其现有状态。
// 接收方用 Store.FetchPackage 取包（每次重新检查绑定授权与患者状态），
// 用 Store.SubmitReceipt 凭交换标识与包摘要登记接受或拒绝回执；授权失效或
// 患者停用后取包被拒绝，但此前包的回执仍可登记。内部使用者可用
// Store.GetExchange / Store.ListExchanges 按患者查看原包与回执，停用后亦可。
//
// 停用档案（Store.DeactivatePatient）后禁止一切写入与接收方读取，
// 内部使用者仍可查看历史。生效、更正、授权创建与撤回、档案停用、交换创建与
// 首次回执登记都会写入仅供内部使用者按患者查看的审计事件。关闭后用同一目录
// 重新 [Open]，档案、版本、授权状态、交换、回执与审计历史全部保留；
// 授权是否到期始终按本次读取时间判断。
//
// [Ready] 保持基线行为：包可以加载时始终返回 true。
package clinical

// Ready 表示基线可以运行。
func Ready() bool { return true }

