// view 在只读快照上执行查询。
func (s *Store) view(fn func(*snapshot) error) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.data == nil {
		return ErrClosed
	}
	return fn(s.data)
}

// viewAt 在只读快照上执行依赖“当前时刻”的查询，并返回该时刻。
