	}

	// 请求发出时整类授权仍有效；核对时刻整类已到期，只剩 d1 的限定授权。
	clk.t = wholeEnd.Add(-time.Minute)
	res, err := readAfterWait(t, s, clk, wholeEnd, func() (ReadResult, error) {
		return s.Read(rcv, pid, eid, Diagnosis)
	})
