		t.Fatalf("records = %d, want exactly 1", len(res.Records))
	}
	if res.Records[0].RecordID != d1.ID {
		t.Fatalf("got record %q, want only selectively granted %q", res.Records[0].RecordID, d1.ID)
	}
}

